export function drawForeground(ctx,map,heroX,heroY,heroHeight){
 for(const o of FOREGROUND){
  if(heroY>=o.depth)continue;
  const xs=o.points.map(p=>p[0]),ys=o.points.map(p=>p[1]);
  if(heroX+22<Math.min(...xs)||heroX-22>Math.max(...xs)||heroY<Math.min(...ys)||heroY-heroHeight>Math.max(...ys))continue;
  ctx.save();ctx.beginPath();o.points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.clip();ctx.drawImage(map,0,0,1672,940);ctx.restore();
 }
}
